  ('epson-tm-m30ii-nt-thermal-usb-lan', 'Epson TM-M30II-NT Thermal - USB/LAN', 'eatOS - Restaurant management made simple', NULL, '[]', '<p><meta charset="utf-8">Epson C31CE95022 Series TM-M30 Thermal Receipt Printer, Autocutter, USB, Ethernet, Energy Star, Black</p>', 299, NULL, 'USD', 1, 'published', '2021-08-25T04:04:36-04:00', '2026-08-29T07:43:11-04:00'),
  ('epson-tm-t20iii-thermal-usb', 'Epson TM-T20III Thermal - USB', 'eatOS - Restaurant management made simple', NULL, '[]', '<p><span>The TM-T20II is an affordable POS receipt printer with fast print speeds and economical features. The combination of its fast print speeds, high reliability and economical operation, make this Energy Star-qualified printer a must-have for small retail and specialty stores, hospitality venues and grocery stores.</span></p>', 169, NULL, 'USD', 1, 'published', '2021-08-25T04:02:07-04:00', '2026-08-29T07:43:11-04:00'),
  ('epson-tm-u220b-dot-matrix-lan', 'Epson TM-U220B - DOT Matrix - LAN', 'eatOS - Restaurant management made simple', NULL, '[]', '<p><span>The TM-U220 printers are designed to be compatible with existing systems built around a TM-U210. These systems can be upgraded simply by dropping in a TM-U220. Moreover, since the external dimensions are nearly identical, there is no need to change the installation environment. The transition to the new model is as smooth as can be.</span></p>', 289, NULL, 'USD', 1, 'published', '2021-08-25T04:00:33-04:00', '2026-08-29T07:43:11-04:00'),
